UNION ALL SELECT id, 'C', 'process_step_confusion', $a9C$Confusing a clean two-cell-stage split (individual placentas, separate twins) with the late incomplete split that causes joining$a9C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a9D$A correct clean blastocyst-stage split (shared placenta) paired with a wrong resorption mechanism, when joining actually requires the split to be incomplete$a9D$ FROM q;

-- Q10 [Cleavage | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub10$Cleavage$sub10$, $qt10$A researcher measures the total volume of a sea-urchin embryo at the 1-cell zygote, 4-cell, and 8-cell stages and counts the cells at each point. Which result should she expect to record?$qt10$, $op10$[{"label": "A", "text": "The cell number rises and the total embryo volume roughly doubles with each successive division."}, {"label": "B", "text": "The cell number rises while each new cell grows back to the original cell size before the next division."}, {"label": "C", "text": "The cell number rises while the total embryo volume stays about the same as the original zygote."}, {"label": "D", "text": "The cell number stops rising at the 8-cell stage while each existing cell enlarges to grow the embryo."}]$op10$::jsonb, 'C', $ex10$This is a Biology question that falls under the content category 'Early Embryonic Development'. The answer is C because cleavage is a series of mitotic divisions that subdivide the zygote into progressively smaller cells without any net growth, so the multicellular embryo remains about the same size as the original egg. OpenStax Biology states that "the egg is subdivided by successive cleavages into smaller and smaller cells, with no actual cell growth," and notes in Figure 27.3 that "the 8-cell stage and the blastula are about the same size as the original zygote." OpenStax Anatomy & Physiology reinforces this, stating that "although each cleavage results in more cells, it does not increase the total volume of the conceptus." Therefore the cell count climbs (1 to 4 to 8) while the summed volume of all cells stays roughly constant. (Choice A) Incorrect; cleavage involves "no actual cell growth," so the total volume does not double each round—this confuses cleavage with growth. (Choice B) Incorrect; the blastomeres get "smaller and smaller" and do not grow back to the original size between divisions. (Choice C) Correct; the embryo is subdivided into more, smaller blastomeres while total volume is "about the same size as the original zygote." (Choice D) Incorrect; cleavage continues past the 8-cell stage to the morula and blastula, and the embryo does not enlarge by enlarging existing cells. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defining feature of cleavage—division without growth—stated directly in the text.$ex10$, 'easy', '2C', $cc10$Early Embryonic Development$cc10$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a10A$Treating cleavage as growth-coupled division, so total volume doubles each round$a10A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a10B$Correct that cells divide, but falsely adds a growth-recovery step restoring original cell size$a10B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a10D$Halting cleavage at the 8-cell stage and substituting cell enlargement for further division$a10D$ FROM q;

-- Q11 [Cleavage | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub11$Cleavage$sub11$, $qt11$A developmental biologist follows a single amphibian zygote as it undergoes successive cleavage divisions, noting that the embryo as a whole does not enlarge even as the number of cells climbs from 2 to 4 to 8. She measures the average nuclear-to-cytoplasmic ratio of an individual blastomere at each stage. What does she most likely observe as cleavage proceeds?$qt11$, $op11$[{"label": "A", "text": "The nuclear-to-cytoplasmic ratio falls, because the nucleus is repeatedly halved among daughter cells while the cytoplasm is conserved."}, {"label": "B", "text": "The nuclear-to-cytoplasmic ratio stays constant, because both nuclear DNA and cytoplasm are duplicated together before every division."}, {"label": "C", "text": "The nuclear-to-cytoplasmic ratio stays constant, because each blastomere grows new cytoplasm in proportion to its replicated DNA."}, {"label": "D", "text": "The nuclear-to-cytoplasmic ratio rises, because each blastomere keeps a full replicated genome while the fixed egg cytoplasm is split among more cells."}]$op11$::jsonb, 'D', $ex11$This is a Biology question that falls under the content category 'Early Embryonic Development'. The answer is D because cleavage is a series of ordinary mitotic divisions in which the DNA is fully replicated each cycle, so every blastomere inherits a complete nuclear genome, yet the egg is merely subdivided "into smaller and smaller cells, with no actual cell growth," and the divisions occur "without changing the total volume." With nuclear content per cell held roughly constant but the fixed pool of egg cytoplasm partitioned among an ever-larger number of cells, the cytoplasm per blastomere shrinks at each round, so the nuclear-to-cytoplasmic ratio climbs as cleavage advances. (Choice A) is wrong because cleavage is mitotic: the nucleus is not "halved" among daughters but fully replicated, so each daughter receives a complete genome rather than a diminishing share, and the predicted fall is the reverse of what occurs. (Choice B) is wrong because, although nuclear DNA is indeed duplicated before each division, the cytoplasm is not duplicated alongside it; the embryo undergoes "no actual cell growth," so the two are not held in proportion. (Choice C) is wrong because no new cytoplasm is synthesized during cleavage; the text states the process makes use of the egg's pre-existing "abundant cytoplasm" while dividing "without changing the total volume," so the cytoplasm cannot grow to match the DNA. (Choice D) is correct because a constant per-cell genome divided into a steadily shrinking cytoplasmic share yields a rising ratio. This is a Scientific Reasoning and Problem Solving question because it requires combining the genetic outcome of mitosis with the fixed-cytoplasm constraint of cleavage to predict the direction of change in a derived ratio rather than recalling a stated fact.$ex11$, 'medium', '2C', $cc11$Early Embryonic Development$cc11$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a11A$Predicts the ratio moves in the opposite direction by wrongly treating mitotic nuclear division as a halving/dilution of nuclear material rather than full replication.$a11A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a11B$Correctly notes DNA is replicated each cycle but falsely couples it with simultaneous cytoplasmic duplication, ignoring the 'no cell growth' constraint to force a constant ratio.$a11B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a11C$Assumes blastomeres synthesize new cytoplasm proportional to DNA, directly contradicting that cleavage subdivides fixed cytoplasm without increasing total volume.$a11C$ FROM q;

-- Q12 [Cleavage | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub12$Cleavage$sub12$, $qt12$A developmental biologist works with an early-stage embryo undergoing determinate (mosaic) cleavage, in which each blastomere's developmental fate is already fixed. Using a micropipette, she removes one blastomere and allows the remaining cells to continue developing. What outcome does she most likely observe in the remaining embryo?$qt12$, $op12$[{"label": "A", "text": "It develops with certain structures missing or fails to develop at all, because the lost blastomere's assigned fate cannot be taken over by any other cell."}, {"label": "B", "text": "It develops completely normally, because neighboring blastomeres detect the loss and regenerate the missing cell's full set of structures."}, {"label": "C", "text": "It develops normally while the removed blastomere on its own forms a second, smaller complete embryo, because that cell can still produce any cell type."}, {"label": "D", "text": "It develops normally but at a slower rate, because the remaining blastomeres must each divide one extra time to replace the lost cell."}]$op12$::jsonb, 'A', $ex12$This is a Biology question that falls under the content category 'Early Embryonic Development'. The answer is A because in determinate (mosaic) cleavage the developmental fate of each blastomere is already fixed, so a cell cannot give rise to any type other than its assigned one, and removing it leaves a gap no other cell can fill. The text states that in determinate cleavage "the developmental fate of each embryonic cell is already determined" and "a given cell does not have the ability to develop into any cell type other than its original destination," so that "removal of a blastomere from an embryo with determinate cleavage can result in missing structures, and embryos that fail to develop." The capacity of neighbors to compensate, and the ability of an isolated blastomere to form a twin, are described as features of indeterminate cleavage, not determinate cleavage, so they cannot apply to this embryo. The scenario therefore predicts a deficient embryo once a committed cell is taken away. (Choice A) Correct: with fates fixed, the missing blastomere's contribution is lost and the embryo develops abnormally or not at all. (Choice B) Incorrect: compensation by adjacent cells is the hallmark of indeterminate cleavage, where "adjacent cells are able to compensate for the missing cells," the reverse of the determinate case here. (Choice C) Incorrect: an isolated cell forming a second complete embryo (twinning) occurs in indeterminate cleavage, where separated blastomeres can produce "twins (clones)," not in determinate cleavage. (Choice D) Incorrect: cleavage subdivides the egg "with no actual cell growth," and a fixed-fate cell cannot be replaced simply by extra divisions, so a slower-but-normal outcome is not predicted. This is a Scientific Reasoning and Problem Solving question because it requires applying the definition of determinate cleavage to a novel experimental manipulation and predicting the resulting phenotype rather than recalling a stated fact.$ex12$, 'medium', '2C', $cc12$Early Embryonic Development$cc12$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
