UNION ALL SELECT id, 'B', 'partial_truth', $a19B$Correct on low yolk and holoblastic cleavage but wrongly denies that a blastocoel forms$a19B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a19C$Couples low yolk to cytoplasmic/volume gain during cleavage, contradicting that cleavage adds no volume$a19C$ FROM q;

-- Q20 [Implantation & Extraembryonic Membranes | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub20$Implantation & Extraembryonic Membranes$sub20$, $qt20$A blastocyst implants in the uterine wall, and a researcher tracks the descendants of its outer shell of cells through the second week of development. The researcher predicts that this population will build the chorionic sac and the embryo's contribution to the placenta. Which cell population is the researcher following?$qt20$, $op20$[{"label": "A", "text": "The trophoblast, the outer cell layer of the blastocyst"}, {"label": "B", "text": "The inner cell mass, the embryo-forming cells of the blastocyst"}, {"label": "C", "text": "The epiblast, the upper layer of the embryonic disc"}, {"label": "D", "text": "The hypoblast, the lower layer of the embryonic disc"}]$op20$::jsonb, 'A', $ex20$This is a Biology question that falls under the content category 'Early Embryonic Development'. The answer is A because the trophoblast is the outer shell of the blastocyst, and the text states these cells develop into the chorionic sac and the fetal portion of the placenta. In the blastocyst, the cells separate into an inner cell mass fated to become the embryo and an outer shell of trophoblasts; it is the trophoblast lineage, not the embryo-forming cells, that gives rise to the chorion and the embryonic side of the placental exchange organ. The epiblast and hypoblast are layers of the later embryonic disc that form the amnion and yolk sac respectively, so neither produces the chorion. (Choice A) Correct: the trophoblast forms the outer shell and develops into the chorionic sac and the fetal portion of the placenta. (Choice B) The inner cell mass is fated to become the embryo proper, not the placenta. (Choice C) The epiblast extends around the amniotic cavity to form the amnion, not the chorion. (Choice D) The hypoblast extends into the blastocyst cavity to form the yolk sac, not the chorion. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling which embryonic cell population is the established precursor of the chorion and the fetal portion of the placenta.$ex20$, 'easy', '2C', $cc20$Early Embryonic Development$cc20$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a20B$Embryo-forming cells also build the placental exchange surface$a20B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a20C$Epiblast forms the amnion, not the chorion$a20C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a20D$Hypoblast forms the yolk sac, not the chorion$a20D$ FROM q;

-- Q21 [Implantation & Extraembryonic Membranes | medium | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Embryogenesis & Development', $sub21$Implantation & Extraembryonic Membranes$sub21$, $qt21$An obstetrician monitoring a fetus identifies that one of the three vessels in the umbilical cord has become selectively occluded, and the fetus now shows signs of oxygen and nutrient deprivation. Occlusion of which cord vessel most directly accounts for the loss of oxygenated, nutrient-rich blood being delivered from the placenta to the fetus?$qt21$, $op21$[{"label": "A", "text": "One of the two umbilical arteries, because the arteries deliver oxygen-rich, nutrient-laden blood from the placenta to the fetus"}, {"label": "B", "text": "The single umbilical vein, because it carries oxygen-rich blood and nutrients from the placenta to the fetus"}, {"label": "C", "text": "The single umbilical artery, because oxygenated blood returns to the fetus through one artery while two veins carry waste away"}, {"label": "D", "text": "Both umbilical arteries together, because they return cleaned, oxygenated blood to the fetus after filtration in the chorionic villi"}]$op21$::jsonb, 'B', $ex21$This is a Biology question that falls under the content category 'Early Embryonic Development'. The answer is B because the single umbilical vein is the one cord vessel that carries oxygen-rich blood and nutrients from the placenta to the fetus, so occluding it cuts off that supply. The text states that "nutrients and oxygen are carried from the pregnant person to the fetus through the single umbilical vein" and that the "umbilical vein... carries oxygen-rich blood from the pregnant person to the fetal... heart," while the "two umbilical arteries" carry "deoxygenated blood and wastes from the fetus" toward the placenta. Because direction and oxygenation in the cord are reversed relative to the systemic pattern (here the vein is the oxygenated, fetus-bound vessel and the arteries are deoxygenated and placenta-bound), blocking the vein—not an artery—starves the fetus of oxygen and nutrients. (Choice A) is incorrect because the umbilical arteries carry deoxygenated, waste-laden blood away from the fetus to the placenta, not oxygen-rich blood toward the fetus. (Choice B) is correct because the single umbilical vein is the vessel that conducts oxygen-rich, nutrient-laden blood from the placenta to the fetus. (Choice C) is incorrect because the cord contains two arteries and one vein, and it is the vein, not an artery, that is oxygenated and fetus-bound. (Choice D) is incorrect because, although capillaries in the chorionic villi do filter fetal wastes and return clean, oxygenated blood, that cleaned blood returns to the fetus through the umbilical vein rather than the arteries. This is a Scientific Reasoning and Problem Solving question because it requires applying the directional and oxygenation roles of the cord vessels to predict the consequence of a specific selective occlusion.$ex21$, 'medium', '2C', $cc21$Early Embryonic Development$cc21$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a21A$Assigns the oxygenated, fetus-bound delivery role to the umbilical arteries, reversing the true direction (arteries carry deoxygenated blood to the placenta)$a21A$ FROM q
UNION ALL SELECT id, 'C', 'scale_unit_error', $a21C$Miscounts the vessels (one artery / two veins instead of two arteries / one vein) and mislabels the artery as the oxygenated vessel$a21C$ FROM q
