SELECT id, 'A', 'partial_truth', $a25A$Names a real extraembryonic membrane (amnion) but attributes the wrong function—the protective fluid sac is confused with the excretory duct.$a25A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a25B$Cites the correct outermost membrane (chorion) and a true fact about it, but it gives rise to the placenta, not the bladder.$a25B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a25C$Confuses the parent structure (yolk sac) with the outpocketing that buds from it (allantois), conflating two sequential developmental steps.$a25C$ FROM q;

